using System;using System.Threading;using ChooGuard.Seeded;using Newtonsoft.Json;public static class LiveNativeStatusProbe{public static int Main(){try{SubscriptionConnection connection;string reason;if(!SubscriptionConnection.TryLoad(out connection,out reason)){Console.WriteLine(JsonConvert.SerializeObject(new{passed=false,error=reason}));return 1;}using(var ct=new CancellationTokenSource(TimeSpan.FromSeconds(5))){var reply=connection.CreateControlClient(()=>false).RefreshAsync(ct.Token).GetAwaiter().GetResult();var state=reply.State;bool passed=state.Protocol=="multi-provider-subscription-v1"&&state.Subscription.Selection==null&&!state.Subscription.CloudEnabled&&!state.InitialAllowed;Console.WriteLine(JsonConvert.SerializeObject(new{passed,protocol=state.Protocol,provider_rows=state.Providers.Count,selection_absent=state.Subscription.Selection==null,subscription_disabled=!state.Subscription.CloudEnabled,initial_allowance_absent=!state.InitialAllowed,models_cached=state.Models.Count,native_ready=state.Subscription.Ready,status_gets=1,inference_posts=0}));return passed?0:1;}}catch(NativeProviderControlException e){Console.WriteLine(JsonConvert.SerializeObject(new{passed=false,error=e.Code}));return 1;}catch(Exception){Console.WriteLine("{\"passed\":false,\"error\":\"read_only_interop_failed\"}");return 1;}}}